  "landing.clarityTitle": "\u300a\u6e05\u6670\u6cd5\u6848\u300b\u53c2\u8bae\u9662\u6295\u7968",
  "landing.clarityBody": "\u7f8e\u56fd\u53c2\u8bae\u9662\u9884\u8ba1\u5c06\u5bf9\u300a\u6570\u5b57\u8d44\u4ea7\u5e02\u573a\u6e05\u6670\u6cd5\u6848\u300b\u8fdb\u884c\u9996\u6b21\u7a0b\u5e8f\u6027\u6295\u7968\u2014\u2014\u8be5\u6cd5\u6848\u5c06\u4e3a\u7f8e\u56fd\u52a0\u5bc6\u884c\u4e1a\u5e26\u6765\u660e\u786e\u7684\u6cd5\u5f8b\u6846\u67b6\u3002\u8fd9\u53ef\u80fd\u662f\u7f8e\u56fd\u52a0\u5bc6\u9886\u57df\u6700\u5177\u5f71\u54cd\u529b\u7684\u76d1\u7ba1\u65f6\u523b\u4e4b\u4e00\u3002",
  "landing.clarityNote": "\u9884\u8ba1 2026 \u5e74 9 \u6708 15 \u65e5 \u00b7 \u542f\u52a8\u8fa9\u8bba\u7684\u7a0b\u5e8f\u6027\u6295\u7968",
  "landing.clarityLiveTitle": "\u6295\u7968\u5468\u5230\u4e86",
  "landing.clarityLiveBody": "\u53c2\u8bae\u9662\u5bf9\u300a\u6e05\u6670\u6cd5\u6848\u300b\u7684\u7a0b\u5e8f\u6027\u6295\u7968\u5373\u5c06\u4e3e\u884c\u3002\u5173\u6ce8\u4e0b\u65b9\u5934\u6761\u4e86\u89e3\u7ed3\u679c\u2014\u2014\u5b83\u5c06\u5851\u9020\u6bcf\u4f4d Voicescape \u521b\u4f5c\u8005\u6b63\u5728\u5efa\u8bbe\u7684\u672a\u6765\u3002",
  "landing.halvingLabel": "\u51cf\u534a\u5012\u8ba1\u65f6",
