  "landing.halvingBtcMeta": "\u533a\u5757 1,050,000 \u00b7 \u5956\u52b1 3.125 \u2192 1.5625 BTC",
  "landing.halvingLtc": "\u83b1\u7279\u5e01\u51cf\u534a",
  "landing.halvingLtcMeta": "\u533a\u5757 3,360,000 \u00b7 \u5956\u52b1 6.25 \u2192 3.125 LTC",
